def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    def generate_permutations(lst, index, result, current):
        if index == len(lst):
            result.append(current)
            return
        for i in range(len(lst)):
            if i not in current:
                generate_permutations(lst, index + 1, result, current + [i])

    permutations = []
    generate_permutations(lst, 0, permutations, [])

    for perm in permutations:
        concat_str = ''.join([lst[i] for i in perm])
        if is_balanced(concat_str):
            return 'Yes'

    return 'No'

